insert into public.reference_photos (categoria, tipo_peca, pose, data_comemorativa, nome_referencia, prompt_mestre, perfis_sugeridos, aspecto, ordem, status) values ('data_comemorativa', 'Colar', 'Still com Tema', 'Dia dos Namorados', 'dia-dos-namorados_colar_still-com-tema', 'Utilize exclusivamente a joia da fotografia anexada como referência do produto. Preserve com fidelidade absoluta: formato, proporções, espessura, acabamento, brilho, textura, cor do metal, pedras (corte, tamanho e posição), cravação, fechos e elos, e todos os demais detalhes originais da peça. Não redesenhe, reinterprete, estilize, complete, corrija ou invente nenhuma característica da joia — reproduza exatamente o que existe na imagem original. Não utilize a foto anexada como referência de cenário, iluminação, enquadramento ou composição — ela serve apenas para identificar a peça e seus detalhes exatos; remova completamente quaisquer objetos, mãos ou fundos presentes na foto original.
Composição: Apoie o colar completamente sobre a superfície, deixando a corrente cair em curvas amplas e orgânicas, como o peso natural do metal realmente se comportaria — nunca reproduza o formato exato da foto original. Nunca crie círculos perfeitos, ovais, corações, gotas ou curvas espelhadas/simétricas dos dois lados; cada lado da corrente deve ter um desenho diferente, com raios e comprimentos de curva variados. Se houver pingente, ele deve ser o ponto focal da composição.
Tema visual: Dia dos Namorados. Paleta de cores: tons de vermelho e vinho. Elementos/props de cena: pétalas de rosa vermelha, velas acesas desfocadas ao fundo. Clima geral: romântico, intimista, iluminação quente e noturna.
Fotografia editorial de joias com estética minimalista, sofisticada e contemporânea, semelhante a campanhas de marcas de luxo. A peça deve estar apoiada sobre um tecido branco ou off-white premium, fosco, encorpado, com textura delicada semelhante a crepe de seda estruturado, moldado à mão em ondas amplas e curvas orgânicas — nunca padrões repetitivos, simetria perfeita ou dobras geométricas/espirais matematicamente exatas (isso denuncia aparência de imagem gerada por IA). Câmera em ângulo de aproximadamente 45°, lente macro equivalente a 85-100mm, enquadramento em close-up com a peça ocupando cerca da metade da imagem. Iluminação natural extremamente suave e difusa, como luz de uma grande janela lateral, criando sombras delicadas entre as dobras do tecido. Paleta restrita a branco quente, marfim e creme suave. Não adicionar flores, folhas, pedras decorativas, madeira, embalagens, mãos, pessoas ou qualquer elemento decorativo.
Qualidade: altíssima resolução, nitidez máxima na joia, excelente alcance dinâmico, texturas naturais, reflexos fisicamente corretos, cores absolutamente fiéis, acabamento fotográfico profissional. Eliminar completamente aparência de renderização 3D, ruído digital, granulado, halos ou qualquer aspecto artificial típico de imagem gerada por IA. A peça não deve parecer flutuando, tombada ou fora de escala — preserve rigorosamente suas proporções e comportamento físico real. Antes de finalizar, confirme que a peça gerada corresponde exatamente, em quantidade e em detalhes, à peça da imagem original. Formato final da imagem: 3:4 (vertical).', NULL, '3:4 (vertical)', 11, 'a_gerar') on conflict (nome_referencia) do nothing;
insert into public.reference_photos (categoria, tipo_peca, pose, data_comemorativa, nome_referencia, prompt_mestre, perfis_sugeridos, aspecto, ordem, status) values ('data_comemorativa', 'Colar', 'Lifestyle com Tema', 'Dia dos Namorados', 'dia-dos-namorados_colar_lifestyle-com-tema', 'Utilize exclusivamente a joia da fotografia anexada como referência do produto. Preserve com fidelidade absoluta: formato, proporções, espessura, acabamento, brilho, textura, cor do metal, pedras (corte, tamanho e posição), cravação, fechos e elos, e todos os demais detalhes originais da peça. Não redesenhe, reinterprete, estilize, complete, corrija ou invente nenhuma característica da joia — reproduza exatamente o que existe na imagem original. Não utilize a foto anexada como referência de cenário, iluminação, enquadramento ou composição — ela serve apenas para identificar a peça e seus detalhes exatos; remova completamente quaisquer objetos, mãos ou fundos presentes na foto original.
Composição: mostrar apenas o colo, as clavículas e a parte inferior do pescoço, terminando imediatamente abaixo da mandíbula, evidenciando a peça de forma natural.
Tema visual: Dia dos Namorados. Paleta de cores: tons de vermelho e vinho. Elementos/props de cena: pétalas de rosa vermelha, velas acesas desfocadas ao fundo. Clima geral: romântico, intimista, iluminação quente e noturna.
Fotografia editorial extremamente realista para catálogo premium de joias, produzida como uma campanha de joalheria de luxo. Enquadramento fechado, mostrando apenas o colo, as clavículas e a parte inferior do pescoço, terminando imediatamente abaixo da mandíbula — nunca mostrar rosto, olhos, boca, nariz, cabelo ou outras partes do corpo além das indicadas. A pele deve ter aparência extremamente natural, saudável e uniforme, com tom: [PERFIL]. Criar uma única faixa de sombra diagonal, contínua e bem definida, inclinada aproximadamente 45°, atravessando a composição como luz entrando por uma janela — a sombra nunca deve cruzar ou escurecer a peça, que deve permanecer completamente iluminada e em destaque. Vestuário minimalista em tecido acetinado ou seda fosca, em tom off-white, extremamente discreto para não competir com a joia. Lente equivalente entre 85mm e 105mm, profundidade de campo rasa — a pele pode ficar levemente desfocada, mas a peça deve permanecer perfeitamente nítida. Fundo neutro (cinza quente muito suave ou bege acinzentado), sem textura, objetos ou elementos decorativos. Não adicionar outras joias, acessórios ou maquiagem chamativa.
Qualidade: altíssima resolução, nitidez máxima na joia, excelente alcance dinâmico, texturas naturais, reflexos fisicamente corretos, cores absolutamente fiéis, acabamento fotográfico profissional. Eliminar completamente aparência de renderização 3D, ruído digital, granulado, halos ou qualquer aspecto artificial típico de imagem gerada por IA. A peça não deve parecer flutuando, tombada ou fora de escala — preserve rigorosamente suas proporções e comportamento físico real. Antes de finalizar, confirme que a peça gerada corresponde exatamente, em quantidade e em detalhes, à peça da imagem original. Formato final da imagem: 3:4 (vertical).', 'Mulher jovem (18-25), pele clara | Mulher adulta (30-45), pele morena | Mulher adulta (30-45), pele negra | Mulher idosa (60+), pele clara', '3:4 (vertical)', 12, 'a_gerar') on conflict (nome_referencia) do nothing;
